import{_ as a,a0 as p,w as l,s as d,I as i,x as s,a1 as e,A as o,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 中不使用功能键在 TTY 之间切换 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中不使用功能键在 TTY 之间切换 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中不使用功能键在 TTY 之间切换 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中不使用功能键在 TTY 之间切换 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180822 How To Switch Between TTYs Without Using Function Keys In Linux","title":"如何在 Linux 中不使用功能键在 TTY 之间切换","tag":"201809","desc":""},"relativePath":"201809/20180822 How To Switch Between TTYs Without Using Function Keys In Linux.md","filePath":"[post].md"}'),r={name:"201809/20180822 How To Switch Between TTYs Without Using Function Keys In Linux.md"};function h(g,t,T,k,c,b){const n=p("Link");return l(),d("div",null,[t[24]||(t[24]=i("h1",{id:"如何在-linux-中不使用功能键在-tty-之间切换",tabindex:"-1"},[s("如何在 Linux 中不使用功能键在 TTY 之间切换 "),i("a",{class:"header-anchor",href:"#如何在-linux-中不使用功能键在-tty-之间切换","aria-label":"Permalink to “如何在 Linux 中不使用功能键在 TTY 之间切换”"},"​")],-1)),t[25]||(t[25]=i("p",null,[i("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/08/Switch-Between-TTYs-720x340.png",alt:""})],-1)),i("p",null,[t[1]||(t[1]=s("本简要指南介绍了在类 Unix 操作系统中如何在不使用功能键的情况下切换 TTY。在进一步讨论之前，我们将了解 TTY 是什么。正如在 AskUbuntu 论坛的一个",-1)),e(n,{href:"https://askubuntu.com/questions/481906/what-does-tty-stand-for"},{default:o(()=>[...t[0]||(t[0]=[s("答案",-1)])]),_:1}),t[2]||(t[2]=s("中所提到的，",-1)),t[3]||(t[3]=i("strong",null,"TTY",-1)),t[4]||(t[4]=s("这个词来自 ",-1)),t[5]||(t[5]=i("strong",null,"T",-1)),t[6]||(t[6]=s("ele",-1)),t[7]||(t[7]=i("strong",null,"TY",-1)),t[8]||(t[8]=s("pewriter（电传打字机）。在 Unix 的早期，连接到计算机的用户终端就是机电的电传机或电传打字机（简称 tty）。从那时起，TTY 这个名称继续用于纯文本控制台。如今，所有文本控制台都代表虚拟控制台，而不是物理控制台。TTY 命令打印连接到标准输入的终端的文件名。",-1))]),t[26]||(t[26]=u(`<h3 id="在-linux-中切换-tty" tabindex="-1">在 Linux 中切换 TTY <a class="header-anchor" href="#在-linux-中切换-tty" aria-label="Permalink to “在 Linux 中切换 TTY”">​</a></h3><p>默认情况下，Linux 中有 7 个 tty。它们被称为 tty1、tty2……tty7。1 到 6 的 tty 只是命令行。第 7 个 tty 是 GUI（你的 X 桌面会话）。你可以使用 <code>CTRL+ALT+Fn</code> 键在不同的 TTY 之间切换。例如，要切换到 tty1，我们按下 <code>CTRL+ALT+F1</code>。这就是 tty1 在 Ubuntu 18.04 LTS 服务器中的样子。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/tty1.png" alt=""></p><p>如果你的系统没有 X 会话， 只需要按下 <code>Alt+Fn</code> 键，不需要按下 <code>CTRL</code>。</p><p>在某些 Linux 版本中（例如，从 Ubuntu 17.10 开始），登录屏开始使用 1 号虚拟控制台。因此，你需要按 <code>CTRL+ALT+F3</code> 到 <code>CTRL+ALT+F6</code> 来访问虚拟控制台。要返回桌面环境，请在 Ubuntu 17.10 及更高版本上按下 <code>CTRL+ALT+F2</code> 或 <code>CTRL+ALT+F7</code>。</p><p>目前为止我们看到我们可以使用 <code>CTRL+ALT+Fn</code>（<code>F1</code> - <code>F7</code>）在 TTY 之间轻松切换。但是，如果出于任何原因你不想使用功能键，那么在 Linux 中有一个名为 <code>chvt</code> 的简单命令。</p><p><code>chvt N</code> 命令让你切换到前台终端 N，这与按 <code>CTRL+ALT+Fn</code> 相同。如果它不存在，则创建相应的屏幕。</p><p>让我们试试显示当前的 tty：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tty</span></span></code></pre></div><p>我的 Ubuntu 18.04 LTS 服务器的示例输出。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/tty-command-output.png" alt=""></p><p>现在让我们切换到 tty2。为此，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chvt 2</span></span></code></pre></div><p>记住你需要在 <code>chvt</code> 命令一同使用 <code>sudo</code>。</p><p>现在，使用命令检查当前的 tty：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tty</span></span></code></pre></div><p>你会看到 tty 现在已经改变了。</p><p>同样，你可以使用 <code>sudo chvt 3</code> 切换到 tty3，使用 <code>sudo chvt 4</code> 切换到 tty4 等等。</p><p>当任何一个功能键不起作用时，<code>chvt</code> 命令会很有用。</p><p>要查看活动虚拟控制台的总数，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fgconsole</span></span>
<span class="line"><span>2</span></span></code></pre></div><p>如你所见，我的系统中有两个活动的虚拟终端。</p><p>你可以使用以下命令查看下一个未分配的虚拟终端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fgconsole --next-available</span></span>
<span class="line"><span>3</span></span></code></pre></div><p>如果虚拟控制台不是前台控制台，并且它没有打开任何进程来读取或写入，并且未在其屏幕上选择任何文本，则它是未使用的。</p><p>要移除未使用的虚拟终端，只需键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ deallocvt</span></span></code></pre></div><p>上面的命令为所有未使用的虚拟控制台释放内核内存和数据结构。简单地说，此命令将释放连接到未使用的虚拟控制台的所有资源。</p><p>有关更多详细信息，请参阅相应命令的手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man tty</span></span>
<span class="line"><span>$ man chvt</span></span>
<span class="line"><span>$ man fgconsole</span></span>
<span class="line"><span>$ man deallocvt</span></span></code></pre></div><p>就是这些了。希望这很有用。还有更多的好东西。敬请关注！</p><p>干杯!</p><hr>`,33)),i("p",null,[t[10]||(t[10]=s("via: ",-1)),e(n,{href:"https://www.ostechnix.com/how-to-switch-between-ttys-without-using-function-keys-in-linux/"},{default:o(()=>[...t[9]||(t[9]=[s("https://www.ostechnix.com/how-to-switch-between-ttys-without-using-function-keys-in-linux/",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=s("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:o(()=>[...t[11]||(t[11]=[s("SK",-1)])]),_:1}),t[16]||(t[16]=s(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[12]||(t[12]=[s("lujun9972",-1)])]),_:1}),t[17]||(t[17]=s(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:o(()=>[...t[13]||(t[13]=[s("geekpi",-1)])]),_:1}),t[18]||(t[18]=s(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[s("wxy",-1)])]),_:1})]),i("p",null,[t[21]||(t[21]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[19]||(t[19]=[s("LCTT",-1)])]),_:1}),t[22]||(t[22]=s(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:o(()=>[...t[20]||(t[20]=[s("Linux中国",-1)])]),_:1}),t[23]||(t[23]=s(" 荣誉推出",-1))])])}const w=a(r,[["render",h]]);export{x as __pageData,w as default};
